"""Build the public research journal with Python's standard library."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent
ORG = 'https://github.com/harshit-ml-research'
SMOKE = ORG + '/agent-eval-smoke-test'
EVAL = ORG + '/param-sft-eval'


def render(filename, title, description, hero, body):
    links = [('index.html', 'Overview'), ('completed.html', 'Completed'), ('current.html', 'Current'), ('compute.html', 'Compute')]
    nav = ''.join(f'<a href="{href}"' + (' aria-current="page"' if filename == href else '') + f'>{label}</a>' for href, label in links)
    document = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title} | Harshit Singh Bhandari</title><meta name="description" content="{description}">
<meta name="theme-color" content="#f4f2eb"><link rel="stylesheet" href="styles.css">
<link rel="canonical" href="https://research.hsbhandari.dev/{'' if filename == 'index.html' else filename}">
<meta property="og:title" content="{title} | Harshit Singh Bhandari"><meta property="og:description" content="{description}"><meta property="og:type" content="website">
</head><body><a class="skip" href="#main">Skip to content</a><div class="wrap">
<header><a class="brand" href="index.html">hsb<span> / research</span></a><nav aria-label="Main navigation">{nav}</nav></header>
<main id="main" class="reveal">{hero}{body}</main>
<footer><span>Harshit Singh Bhandari · IEOR, IIT Bombay</span><span>Updated 01 Oct 2026 · <a href="mailto:harshitsingh@iitb.ac.in">Contact</a> · <a href="{ORG}">GitHub</a></span></footer>
</div></body></html>'''
    (ROOT / filename).write_text(document, encoding='utf-8')


def hero(kicker, title, description, note):
    return f'<section class="hero"><div><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{description}</p></div><div class="hero-note">{note}</div></section>'


render('index.html', 'Research journal', 'A research journal on agent evaluation, SFT model behavior, and the evidence behind benchmark results.',
hero('Field notes / 2026', 'Agents, under<br><em>inspection.</em>', 'A working research journal on what models do, where they fail, and the evidence behind every result.', '<span class="tag">Current investigation</span><p>Tool calling, on about 100 scenarios. Param2 and a couple of other models in that size range. The scenario set is not locked.</p><a class="button" href="current.html">Follow the investigation ↗</a>'),
f'''<div class="section-head"><h2>Research ledger</h2><span class="mono">02 investigations</span></div>
<article class="project"><div class="number">01</div><div><span class="tag done">Completed experiments</span><h3><a href="completed.html">The pipeline works.<br>The agents struggle.</a></h3><p>Granite 3B and public Param2 Thinking passed basic protocol tasks, then failed ten offline SRE incidents through different mechanisms.</p><a href="completed.html">Read the results ↗</a></div><div class="project-facts"><ul class="fact-list"><li>Location <strong>IEOR, IIT Bombay</strong></li><li>Hardware <strong>2 × RTX A5000</strong></li><li>ITBench Lite proxy <strong>0/10, both models</strong></li><li>Period <strong>28 Sep to 01 Oct 2026</strong></li></ul></div></article>
<article class="project"><div class="number">02</div><div><span class="tag">In preparation</span><h3><a href="current.html">Tool calling,<br>measured directly.</a></h3><p>A larger tool-calling evaluation, then supervised traces aimed at that skill. The earlier SRE incident runs stay completed evidence.</p><a href="current.html">See the evaluation plan ↗</a></div><div class="project-facts"><ul class="fact-list"><li>Models <strong>Param2 and peers</strong></li><li>Eval size <strong>About 100 scenarios</strong></li><li>Scenario set <strong>Not chosen yet</strong></li><li>New benchmark results <strong>Not yet available</strong></li></ul></div></article>
<section class="band"><h2>Scores are a starting point.</h2><p>Every conclusion should lead back to an observed answer, a tool call, or a failure in a saved trajectory. <a href="compute.html">The compute ledger</a> records where each experiment ran.</p></section>''')

render('completed.html', 'Completed experiments', 'Completed agent smoke evaluations on IIT Bombay IEOR servers, with scores and observed failure modes.',
hero('01 / Completed experiments', 'First, prove<br><em>the pipeline.</em>', 'Synthetic protocol checks and offline ITBench Lite SRE snapshots, run on the IEOR servers at IIT Bombay.', f'<span class="tag done">Runs complete</span><p>Granite 4.2 3B and the public Param2 17B A2.4B Thinking checkpoint. Complete trajectories were saved for inspection.</p><a class="button" href="{SMOKE}">Open the experiment repo ↗</a>'),
f'''<div class="content"><aside class="aside"><p class="mono">Experiment context</p><p>Server: passpoli<br>Institution: IEOR, IIT Bombay<br>GPUs: 2 × RTX A5000<br>VRAM: 24 GB each</p><p>Granite: private Ollama service.<br>Param2: local Transformers backend.</p><p><a href="compute.html">Compute ledger ↗</a></p></aside><article class="article"><h2>Recorded results</h2><div class="table-scroll"><table><caption>One attempt per task in the reported smoke and final incident runs.</caption><thead><tr><th scope="col">Test</th><th scope="col">Granite 4.2 3B</th><th scope="col">Param2 Thinking</th></tr></thead><tbody><tr><td>Eight synthetic smoke tasks</td><td>6/8 on the verified rerun</td><td>5/8</td></tr><tr><td>Ordinary tasks, excluding empty-output check</td><td>5/7</td><td>4/7</td></tr><tr><td>Expanded synthetic suite</td><td>25/32 complete</td><td>7 direct tasks before interruption</td></tr><tr><td>Ten ITBench Lite SRE snapshots</td><td>0/10 root cause proxy hits</td><td>0/10 root cause proxy hits</td></tr><tr><td>Minimal incident JSON structure</td><td>2/10 valid</td><td>10/10 valid</td></tr><tr><td>Final incident-run tool calls</td><td>80</td><td>0</td></tr></tbody></table></div>
<div class="callout"><p><b>These are focused offline results.</b> The incident score is a deterministic root cause entity proxy using six reference tools. It is not the official ITBench judge score. The interrupted Param2 expanded run does not provide a paired 32-task comparison.</p></div>
<h2>Same score, different failures.</h2><p><b>Param2 skipped the evidence.</b> All ten incidents received the same answer, with no tool calls. The answer invented a checkout pod and cited tools it had not used. Structurally valid JSON did not imply a correct diagnosis.</p><p><b>Granite investigated but did not finish reliably.</b> It used all eight investigation turns per incident, made weak or invalid queries, and usually produced malformed final output. The two structurally valid answers still missed the proxy target.</p>
<h2>What the smoke run established</h2><p>The generic model interface, agent loop, tool execution, trajectory logging, and scoring worked end to end. Model protocol reliability remained inconsistent. One deliberately empty-output task counts as a protocol-check pass, not useful task completion.</p><h2>Reports and evidence</h2><ul><li><a href="{SMOKE}/blob/main/EVALUATION_REPORT_2026-09-30.md">Combined evaluation report</a></li><li><a href="{SMOKE}/blob/main/SMOKE_REPORT.md">First smoke report</a></li><li><a href="{SMOKE}/blob/main/PARAM2_REPORT.md">Public Param2 smoke analysis</a></li><li><a href="{SMOKE}/blob/main/ITBENCH_LITE_REPORT.md">ITBench Lite comparison</a></li></ul><p>Raw trajectories remain local and on the research server; the committed reports contain run identifiers and result tables.</p></article></div>''')

render('current.html', 'Current investigation', 'Current plan: a tool-calling evaluation of about 100 scenarios, then supervised data for that skill.',
hero('02 / Current investigation', 'Tool calling,<br><em>measured directly.</em>', 'Param2 and a couple of other models in that size range, scored on tool calling. About 100 scenarios, still unchosen.', f'<span class="tag">Plan open</span><p>About 100 scenarios. The set, the peer models, and the later training traces are not chosen. No new scores yet.</p><a class="button" href="{EVAL}">Open the evaluation repo ↗</a>'),
'''<div class="content"><aside class="aside"><p class="mono">Current target</p><p>Tool calling<br>About 100 scenarios</p><p>Models: Param2 and a couple of peers in that size range</p><p>The completed SRE incident runs stay on the record. They are not this evaluation.</p></aside><article class="article"><h2>The research question</h2><p>How reliably can these models call tools: choose a tool, form arguments, use the result, and stop? The score is tool-calling behavior on a frozen scenario set: tool choice, arguments, use of the result, and stopping.</p><h2>What is decided</h2><ol class="steps"><li><b>Evaluation first</b><span>About 100 tool-calling scenarios. Param2 plus a couple of models in the same range.</span></li><li><b>Training data second</b><span>Supervised traces from several teachers, aimed at tool calling. The teacher list and the trace count per teacher are still a plan, not a launch.</span></li><li><b>Everything else later</b><span>Tool catalog, scenario source, budgets, and serving choices stay open until they are written down as a run.</span></li></ol><div class="callout"><p><b>No new scores yet.</b> This page states the investigation. It does not report a result.</p></div><h2>Expected research artifacts</h2><p>A frozen scenario manifest, raw generations, parsed tool calls, and a score that separates a valid call from a correct downstream outcome. Training traces, when they exist, will be a separate release from this evaluation set.</p></article></div>''')

